/// <summary>
/// Adds a range to the agreement line query build data source for the ProductUnitOfMeasure field
/// using the sales unit.
/// </summary>
/// <param name="_agreementLineQbds">The QueryBuildDataSource to which the range is added.</param>
void agreementLineAddRange(QueryBuildDataSource _agreementLineQbds)
{
    super(_agreementLineQbds);

    _agreementLineQbds.addRange(fieldNum(AgreementLineQuantityCommitment, ProductUnitOfMeasure)).value(queryValue(salesUnit));
}

/// <summary>
/// Gets the commitment type for this agreement line search.
/// </summary>
/// <returns>
/// The <c>CommitmentType::ProductQuantity</c> value indicating the commitment type is based on product quantity.
/// </returns>
protected CommitmentType getCommitmentType()
{
    return CommitmentType::ProductQuantity;
}
